-- 0009 — o quadro que estava escrito no código.
--
-- Vinte cards migrados de src/lib/kanban/dados.js, que era onde o
-- quadro morava desde que a tela existe. O texto é o mesmo, palavra por
-- palavra: isto é mudança de lugar, não de conteúdo.
--
-- Os ids vêm de lá e não são regerados — eles são a âncora da URL de
-- cada ficha e o alvo de veja_tambem. A ordem preserva a do arquivo,
-- que na raia Arquitetura chegou a ser sequência de dependência.
--
-- autor_id fica nulo: estes cards são anteriores à ideia de autoria.

insert into public.kanban_card
  (id, titulo, raia, coluna, resumo, porque, blocos, veja_tambem, ordem)
values
  ('componentes', 'Componentes (Svelte)', 'arquitetura', 'concluido',
   'Feito em 18/10/2026. Destrava a coluna Bloqueado por BaaS.',
   'Vinha antes ou junto do Supabase, não depois — senão a camada de leitura seria escrita duas vezes.',
   '[{"tipo":"lista","itens":["Leitura de dados remotos. app.js monta o DOM uma vez, a partir de globais já carregados. Dado que chega depois — do Supabase, assíncrono, e que muda quando outra aba marca um tópico — não tem para onde ir.","Criar componente novo fica barato. Drawer, ficha, chip de rodapé e carta hoje são funções que concatenam string e colam no DOM."]},{"tipo":"p","texto":"Custo conhecido: quebra o contrato de ordem de carga do CLAUDE.md (s.async = false, ES5 em IIFE, sem bundler). A trilha vira import, e trilhas.js deixa de ser carregador para virar só manifesto."},{"tipo":"p","texto":"O site ser estático é condição de protótipo, não decisão. O alvo é Svelte na frente, Supabase como BaaS e Deno edge para o que precisa de servidor — push agendado, segredo que não pode ir para o navegador, trabalho que não é do cliente. Os cards devem ser lidos contra esse alvo: limitação que só existe hoje (file://, sem build, sem conta) não é argumento para recusar nada."},{"tipo":"p","texto":"Entregue: SvelteKit com adapter-static, cinco rotas pré-renderizadas e deploy no Pages por Action. O progresso virou uma classe reativa, e é nela e no mural de notas que o Supabase entra — os dois pontos estão isolados e comentados."},{"tipo":"p","texto":"O que não veio junto, e vale saber antes do próximo card: o CSS continua global por tela, então a travessia entre elas é documento novo (data-sveltekit-reload). Enquanto for assim, link interno novo precisa disso e do prefixo base. Abrir por file:// deixou de funcionar."}]'::jsonb, '{}', 0),
  ('supabase', 'Supabase DB + Auth', 'arquitetura', 'concluido',
   'Persistência de verdade. Esquema de pé em 19/10/2026; o site ainda não fala com ele.',
   'Pré-requisito das anotações e da rota condicional.',
   '[{"tipo":"p","texto":"Sete tabelas no Postgres, em cinco migrations versionadas em supabase/migrations/: perfil e progresso_topico; progresso_subassunto e nota; rota_grupo; o gatilho que cria o perfil no cadastro; sessao_estudo e modelo_mes. Todas com RLS e policy auth.uid() = usuario_id."},{"tipo":"p","texto":"A regra que organizou o modelo: o banco guarda o que não se refaz; o localStorage segue dono do que se refaz num clique. Ficaram de fora as etapas fechadas e o revelarPulados — e o tema, que ainda tem um motivo extra: o script inline do app.html o lê antes de o bundle existir."},{"tipo":"p","texto":"O catálogo das trilhas não está no banco, e isso foi decidido. A estrutura de uma trilha é documento, não relação, e a única consulta feita a ela é \"me dá a trilha inteira\". Um dia vira jsonb no mesmo Postgres — o Painel criativo de roadmaps exige isso. Enquanto não vai, nenhuma tabela tem foreign key para o catálogo: trilha e topico_id são text validados pelo app, e o id estável continua contrato do repositório."},{"tipo":"p","texto":"No primeiro login, se houver progresso no localStorage do aparelho, o site pergunta antes de trazer, e o banco vence em empate. Merge automático está fora: o localStorage não guarda quando cada caixa foi marcada, então juntar sozinho seria chute."},{"tipo":"p","texto":"Verificado no remoto em 20/10/2026: as sete tabelas com RLS ligada, uma policy cada e GRANT completo para anon e authenticated. Nada faltando no banco."},{"tipo":"p","texto":"Cliente de pé em 20/10/2026: src/lib/supabase.js, com @supabase/supabase-js e o .env fora do versionamento. Lê de $env/dynamic/public porque o estático falha o build quando a variável não existe — e o site precisa continuar publicável sem conta configurada. É preguiçoso, para não instanciar durante a pré-renderização, e guarda a sessão com try/catch, como o progresso.js faz: em janela anônima a sessão dura só a aba, em vez de a página cair."},{"tipo":"p","texto":"Ligado em 20/10/2026: a conta funciona de ponta a ponta, e o progresso mora no banco. A confirmação de e-mail é por link e não por código, porque o plano gratuito não deixa editar o modelo de e-mail — o passo do código ficou dormente no fluxo, esperando SMTP próprio."},{"tipo":"p","texto":"O localStorage deixou de guardar progresso, e essa foi a decisão que resolveu a divergência: com dois donos do mesmo dado, a mesa contava de um e o mapa do outro, sem ninguém estar errado. Agora sem conta não se marca nada — tentar abre o convite a entrar. Ficaram no navegador só as preferências de leitura por aparelho (etapas fechadas, revelar pulados) e o tema, que o script inline do app.html lê antes do bundle existir."},{"tipo":"p","texto":"O mural de notas e o calendário entraram em 20/10/2026. As notas gravam com uma pausa de 700ms por nota, porque arrastar dispara escrita a cada movimento do ponteiro e digitar a cada tecla — uma ida ao banco por evento seria insustentável."},{"tipo":"p","texto":"O calendário deixou de ser maquete: a grade é calculada do mês de verdade, as sessões vêm do banco e o modelo do mês distribui os dias por déficit proporcional ao ponto do mês. O assunto virou texto livre, porque o que se estuda numa noite raramente tem o nome de uma trilha inteira — e por isso as abas de filtro e a legenda saem do que foi escrito, não de uma lista fixa."},{"tipo":"p","texto":"Uma regra saiu desta sessão, depois de três defeitos iguais: erro nunca vira vazio. Devolver lista vazia quando a consulta falha faz a tela mostrar um mês sem nada que parece verdade — agora cada camada guarda a última falha e o rodapé a mostra."},{"tipo":"p","texto":"Falta: a rota condicional (tabela pronta, sem tela), o modo Google do calendário com OAuth, e prender nota em tópico — o mural sabe soltar, e nada prende."}]'::jsonb, '{}', 10),
  ('login', 'Tela de login e cadastro', 'arquitetura', 'concluido',
   'Feita em 20/10/2026, com e-mail e senha, link de confirmação e entrada pelo Google.',
   'Sem conta, o Supabase não tem a quem atribuir o progresso.',
   '[{"tipo":"p","texto":"A validação por token de 6 dígitos, que era o plano, não saiu: o plano gratuito do Supabase não deixa editar o modelo de e-mail, e o padrão manda link. O passo do código ficou escrito e dormente no fluxo, esperando SMTP próprio — é uma troca de dois seguintes, não um recurso novo."},{"tipo":"p","texto":"O login social do Google entrou em 21/10/2026, com o app publicado em produção. Ele reaproveitou tudo que o link de confirmação já tinha exigido: a volta pela URL com código, a lista de endereços permitidos e o gatilho que cria o perfil. Doze linhas de código novo."},{"tipo":"p","texto":"Vieram junto as páginas de privacidade e termos, que o Google exige para publicar — e que um site com conta e dado de estudo precisaria de qualquer forma."}]'::jsonb, '{}', 20),
  ('botao-conta', 'Botão de conta', 'arquitetura', 'concluido',
   'Na quina da mesa e na ponta do rail, virando menu quando há sessão.',
   'Entrada da conta precisa de lugar fixo, fora da área que muda por trilha.',
   '[{"tipo":"p","texto":"Deslogado é um link; logado abre menu com perfil, zerar progresso e sair. A lixeira do rail foi absorvida por ele: dois caminhos para a ação mais destrutiva da tela era um a mais, e dentro de um menu ela fica mais longe do clique por engano do que estava."},{"tipo":"p","texto":"Enquanto a sessão é desconhecida o botão não aparece. As telas são pré-renderizadas, então um \"Entrar\" no HTML estático piscaria para quem já tem conta."}]'::jsonb, '{}', 30),
  ('ocultar-pulados', 'Ocultar pulados', 'interface', 'concluido',
   'Feito. Pulado sai do mapa, e um chip "× N pulados" na barra do conteúdo revela.',
   'A ficha da rota condicional argumenta que esconder sem explicar faz o tópico parecer inexistente — a janelinha é justamente o que explica, e é por isso que esconder aqui é defensável e lá não é.',
   '[{"tipo":"lista","itens":["Escondido por padrão, e a preferência fica salva por trilha — em roadmap:<trilha>:vista:v1, separada do progresso: é como a pessoa olha a trilha, não o que ela fez nela.","O chip só existe havendo o que esconder, e se acende quando está aberto. Riscado e com ×, ele parece o que guarda.","Grupo e etapa que esvaziam colapsam, pelo mesmo mecanismo que a busca já usava — título de grupo pairando sobre o nada é estranho nas duas situações."]},{"tipo":"p","texto":"Decidido no caminho: com a busca ativa, o pulado escondido continua escondido, e a contagem de resultados conta só o que está na tela. Dizer \"6 encontrados\" com dois invisíveis seria mentir sobre o que se vê — buscar \"come\" devolve 13 com o chip fechado e 14 com ele aberto."}]'::jsonb, array['rota-condicional']::text[], 40),
  ('feito-verde', 'Tópico concluído fica verdinho', 'interface', 'concluido',
   'Feito. Cor no estado feito, somada à marca ■ que já existe.',
   'A cor entrou como reforço, não como único sinal — a marca (□ ► ■ ×) continua distinguindo os quatro estados sem depender dela.',
   '[{"tipo":"p","texto":"A marca do tópico, a do índice e o estado no painel passam a --verde-forte quando o tópico está feito. Só \"feito\" ganha cor: é o tom que passa em contraste nos dois temas a 11px."}]'::jsonb, '{}', 50),
  ('mover-tema', 'Mover tema e reset', 'interface', 'concluido',
   'Feito, em outro lugar: numa coluna própria, não no pé da sidebar.',
   'São controles do site, não da trilha: deixaram de disputar o topo com o conteúdo, que era o ponto.',
   '[{"tipo":"p","texto":"Resolvido diferente do que o card pedia, e vale registrar: em vez do canto inferior da sidebar, os botões foram para o rail — uma coluna só de ações da página, antes da lateral e do mapa. A ordem lá é de consequência crescente: abrir o índice, sair da página, mudar o tema, apagar o progresso."},{"tipo":"p","texto":"A lixeira fica na ponta de baixo, longe do que se clica por engano, e se desabilita sozinha quando não há nada marcado — sozinha num canto, um botão que só anuncia numa região viva invisível lê como botão quebrado."}]'::jsonb, '{}', 60),
  ('inverter-shift', 'Inverter shift+clique', 'interface', 'concluido',
   'Feito. Clique abre o detalhe; shift + clique cicla o estado.',
   'O gesto mais usado deve ser o mais barato — e ler o detalhe é mais frequente que mudar de estado.',
   '[{"tipo":"p","texto":"No toque nada mudou: lá não há Shift, então o toque continua ciclando e o [i] continua abrindo. É a única divergência entre mouse e dedo, e a legenda anuncia a que vale em cada aparelho — como já fazia."},{"tipo":"p","texto":"Saiu junto: o clique com o botão direito abria o detalhe, como atalho para quem não quisesse usar o Shift. Agora o clique simples já faz isso, e sequestrar o menu do navegador para repetir o gesto mais barato da tela não se paga."}]'::jsonb, '{}', 70),
  ('aba-calendario', 'Aba de calendário', 'interface', 'fazer',
   'Grade de mês no próprio site, com modelo do mês por proporção — o que o Google não faz. Layout de pé; falta o comportamento.',
   'É a única parte do projeto que sabe quando você estuda — o roadmap só sabe o quê. O layout está de pé; o que falta é comportamento, e só o último passo (persistência) espera o banco.',
   '[{"tipo":"lista","itens":["Escrever no calendário do site: clicar num dia e anotar o que vai estudar, sem sair da página.","Um modo de cada vez: ou o calendário do Lets learn together, ou o do Google. Nunca os dois.","No modo Google a escrita é chamada de API; no modo Lets learn together é gravação no nosso banco. Mesma tela, dois destinos.","A exclusividade é o que torna o card barato: sem dois donos simultâneos, não existe sincronização — nem merge, nem conflito, nem evento duplicado.","O uso real é por trilha em blocos repetidos (Machine Learning 7:30pm, OpenCV 7:30pm), não por tópico — a grade deve falar essa língua."]},{"tipo":"p","texto":"Decidido: o calendário é dono dos eventos, não uma vista. No modo Google o dono é o Google e a escrita é chamada de API, com OAuth e escopo calendar.events. No modo Lets learn together o dono somos nós e a escrita vai para o Postgres do Supabase — depende do banco e da conta, não do localStorage."},{"tipo":"p","texto":"Consequência na ordem: o modo Google é construível primeiro, porque não espera o banco. O modo Lets learn together não sai antes do Supabase e da conta — o inverso não é indesejável, é impossível."},{"tipo":"p","texto":"O motivo de conectar o Google é notificação: o lembrete chega no celular com o site fechado. Dá para empatar no modo próprio — Web Push disparado por uma Edge Function em Deno, acordada por agendamento no banco — então não é limitação de arquitetura, é trabalho a mais. O que não se empata é o lembrete cair na agenda que a pessoa já abre todo dia, junto com o resto da vida dela, em vez de numa notificação isolada."},{"tipo":"p","texto":"Troca de modo, decidida: o site recusa trocar enquanto houver eventos locais, e oferece exportar antes. Perder plano escrito em silêncio é o pior desfecho, e migrar automático inventa eventos no calendário real de alguém."},{"tipo":"p","texto":"O modelo do mês é o motivo de existir um calendário próprio. No Google a unidade é o evento; aqui é a proporção: declara-se a janela (seg–sáb, a partir das 19h, 1h30 por sessão) e a mistura em dias (50% ML, 40% OpenCV, 10% Projetos), e o mês se preenche. Recorrência não sabe alternar assunto, então isso não é um RRULE — é um dia de cada vez, o que no modo Google significa ~26 chamadas por mês e tratamento de falha parcial."},{"tipo":"lista","itens":["A porcentagem é de dias, não de horas: é o que se confere olhando a grade.","Aplicar nunca reescreve o passado — escreve de hoje em diante, e os dias já estudados contam na cota. Efeito aceito: dia elegível que passou em branco some da cota, em vez de empilhar três sessões na mesma semana para compensar.","Distribuição intercalada, pelo maior déficit: 13 dias seguidos de ML fecham a mesma conta e matam a outra trilha na semana."]},{"tipo":"p","texto":"De pé (layout, out/2026): calendario.html e calendario.css com a grade do mês, a ficha do dia (régua de 17h à 1h, sessões, formulário), a tira do modelo e o diálogo de configuração; a entrada é uma carta na mesa, pregada com alfinete e fora da fileira das trilhas, com cascata nos dias ao clicar. Nada disso tem comportamento ainda."},{"tipo":"lista","itens":["Falta 1 — calendario.js: ?trilha= ligando a aba ativa, abrir e fechar o diálogo, selecionar o dia, escrever à mão. É só DOM, não espera nada.","Falta 2 — distribuição: cotas por maior resto e reparte pelo maior déficit. Lógica pura, e a única parte que erra em silêncio: testar antes de ligar na tela.","Falta 3 — persistência, e aqui o card parava: no modo próprio depende do Supabase e da conta; no modo Google, de OAuth com escopo calendar.events."]},{"tipo":"p","texto":"O modo próprio saiu em 20/10/2026, e com ele a maquete: a grade passou a ser calculada do mês de verdade, as sessões vêm da tabela sessao_estudo e o formulário escreve nelas. O assunto é texto livre, porque o que se estuda numa noite raramente tem o nome de uma trilha inteira — e por isso as abas de filtro e a legenda saem do que foi escrito."},{"tipo":"p","texto":"O modelo do mês também existe: janela de dias e horário, mistura por porcentagem de dias, prévia em dias por assunto e aplicação em lote. A distribuição é lógica pura, testada fora da tela, e usa déficit proporcional ao ponto do mês — pelo déficit absoluto, o assunto de 10% cairia todo no fim do mês. Aplicar nunca reescreve o passado nem toca no que foi escrito à mão."},{"tipo":"p","texto":"Falta o modo Google, que é o que leva o lembrete para a agenda que a pessoa já abre todo dia. E falta qualquer noção de sessão cumprida: a tabela guarda o plano, não o que aconteceu."}]'::jsonb, array['anotacoes', 'supabase', 'login']::text[], 80),
  ('i18n', 'Outros idiomas (i18n)', 'conteudo', 'fazer',
   'Hoje o PT-BR está embutido no markup, nos dados das trilhas e nos próprios identificadores.',
   'Identificador em português é convenção do repositório — traduzir a interface não pode virar renomeação de código.',
   '[]'::jsonb, '{}', 90),
  ('inventario-config', 'Inventário de configuração', 'conteudo', 'fazer',
   'Levantar tudo que é configuração individual e pode ser mudado.',
   'Inventário primeiro; tela de preferências depois, se valer.',
   '[]'::jsonb, '{}', 100),
  ('gerador-rex', 'Gerador de Rex aleatório', 'conteudo', 'fazer',
   'Um Rex novo a cada visita.',
   'Não pode sair igual a um já existente.',
   '[]'::jsonb, '{}', 110),
  ('painel-roadmaps', 'Painel criativo de roadmaps', 'conteudo', 'fazer',
   'Criar e editar trilha pela interface.',
   'Hoje trilha nova é escrever trilhas/<id>/*.js à mão e acertar a contagem no manifesto.',
   '[]'::jsonb, '{}', 120),
  ('anotacoes', 'Notas em post-it', 'interface', 'concluido',
   'Feito em 20/10/2026. Mural de post-its por trilha, com as notas salvas na conta.',
   'Texto escrito não se refaz. É o primeiro dado do projeto que não é reconstruível clicando, e isso muda o contrato de durabilidade da aplicação inteira — um mural perdido não se reconstrói nem com esforço.',
   '[{"tipo":"p","texto":"Mudou de ideia em outubro de 2026: a proposta original era um campo de texto livre por tópico, numa seção nova do drawer. Ficou pequena demais — a maior parte do que se anota estudando não cabe em um tópico só."},{"tipo":"p","texto":"A nota é uma só, vista de dois lugares: nasce solta na trilha e pode ser ancorada num tópico. Ancorada, aparece no mural e no drawer daquele tópico; solta, só no mural. Uma entidade com dois pontos de entrada, e não dois recursos escrevendo a mesma ideia em lugares que nunca se encontram. A nota guarda trilha, texto, cor, tópico opcional e posição opcional."},{"tipo":"lista","itens":["Abas por trilha, como no calendário: notas.html?trilha=ml com uma aba Todas. Mesma solução nas duas telas novas, e cada filtro é um endereço.","A cor é de quem escreve, não da trilha: a trilha já é a aba. Serve para separar dúvida, ideia e erro que não se quer repetir.","Arranjo responsivo, decidido: mural livre arrastando em tela larga, com a posição guardada por nota; grade que flui no celular, mais recente primeiro. A posição é adorno, não dado — nota sem x/y cai numa vaga automática, e no celular x/y é ignorado.","Com BaaS, cai a necessidade de exportar/importar como pré-requisito. Sem BaaS, exportar/importar vinha antes — não junto.","Entrar na busca não é de graça: o corpus de buscar() é titulo + desc + detalhe. Somar a nota é uma linha, mas um tópico que casa só pela anotação aparece no mapa sem pista de por quê. Precisa de um sinal na linha."]},{"tipo":"p","texto":"Entregue em 20/10/2026: as notas gravam na tabela nota com uma pausa de 700ms por nota, porque arrastar dispara escrita a cada movimento do ponteiro e digitar a cada tecla. Prender e soltar existe dos dois lados — o mural prende, e o drawer do roadmap mostra o que está preso naquele tópico, em leitura e não em edição, para não ter dois lugares escrevendo o mesmo texto."},{"tipo":"p","texto":"Os exemplos de mentira saíram junto: nota falsa é indistinguível de real até alguém tentar arrastá-la, e aí o mural mente sobre o que guarda. O que ficou de fora é a busca — um tópico que case só pela anotação ainda apareceria sem pista de por quê."}]'::jsonb, array['supabase', 'login', 'aba-calendario']::text[], 130),
  ('rota-condicional', 'Rota condicional', 'interface', 'fazer',
   'Caminhos alternativos dentro da trilha — pular visão computacional se o objetivo é NLP.',
   'A rota escolhida é estado do usuário, e desde 19/10/2026 tem onde morar: a tabela rota_grupo existe, com RLS, e espera uma tela.',
   '[{"tipo":"lista","itens":["Marcar no grupo, não no tópico: 50 marcações contra 353.","Rotas num rotas.js à parte, seguindo a separação que trilhas.js já faz.","Atenuar o que está fora, não esconder. Reaproveitar o mecanismo do data-oculto da busca, com atributo próprio (data-fora-da-rota) e CSS próprio. Esconder é certo para busca — transitório, explicado pelo campo preenchido — e errado para rota."]},{"tipo":"p","texto":"Decisão pendente, e é a difícil: o que a barra de progresso passa a medir, e quando a faixa de fim de trilha dispara. Posição defendida: a barra mede a rota, e a faixa diz qual rota foi concluída — senão você escolhe um caminho mais curto e a barra continua lembrando do que decidiu não fazer."}]'::jsonb, '{}', 140),
  ('paginas-legais', 'Privacidade e termos', 'conteudo', 'concluido',
   'Duas rotas de texto, escritas no que o site faz de verdade.',
   'Site com conta precisa dizer o que guarda, e quem publica login social é obrigado a provar que disse.',
   '[{"tipo":"p","texto":"Existem por duas razões, nesta ordem: o site guarda dado de pessoa — e-mail, nome, progresso, notas, sessões — e o Google exige os links para publicar o login social."},{"tipo":"p","texto":"Escritas no projeto real, não num modelo: sem rastreamento, sem anúncio, sem compartilhamento, e com o detalhe de que tema e etapas fechadas ficam só no navegador. Modelo genérico diria \"podemos compartilhar com parceiros\", o que seria mentira — e mentira em política de privacidade é o tipo de coisa que volta."}]'::jsonb, array['login', 'excluir-conta']::text[], 150),
  ('excluir-conta', 'Excluir a própria conta', 'arquitetura', 'fazer',
   'Um botão que apaga a conta e tudo que está preso a ela.',
   'Prometer exclusão e cumpri-la à mão é contar com a memória de alguém; e é o único jeito de a promessa valer para quem não conhece o dono do site.',
   '[{"tipo":"p","texto":"A política de privacidade promete exclusão, e hoje ela depende de um e-mail e de alguém abrindo o painel do Supabase. O on delete cascade das tabelas já faz o trabalho pesado: apagar a linha em auth.users leva progresso, notas e sessões junto."},{"tipo":"p","texto":"O que falta é o caminho: o cliente do navegador não pode apagar usuário, então isso pede uma Edge Function em Deno com a chave de serviço — a primeira coisa do projeto que precisa rodar fora do navegador."}]'::jsonb, '{}', 160),
  ('criterios-grupo', 'Critérios por grupo', 'interface', 'analise',
   'Alternativa barata ao quiz; não foi aprovada nem recusada.',
   'Resolve a dúvida que motivou o quiz sem trazer avaliação junto.',
